    <style>
        /* ===== STYLES SPÉCIFIQUES À LA PAGE D'ACCUEIL ===== */
        
        /* Variables supplémentaires */
        :root {
            --gradient-primary: linear-gradient(135deg, #2c5aa0 0%, #1a3a6e 100%);
            --gradient-secondary: linear-gradient(135deg, #ff6b35 0%, #ff8e53 100%);
            --gradient-accent: linear-gradient(135deg, #4ecdc4 0%, #6ae2da 100%);
            --gradient-dark: linear-gradient(135deg, #333333 0%, #555555 100%);
        }
        
        /* Reset et base */
        body {
            overflow-x: hidden;
        }
        
        /* Hero Section */
        .hero-section {
            position: relative;
            background-color: #1a3a6e;
            background-image:
                linear-gradient(135deg, rgba(44, 90, 160, 0.55) 0%, rgba(26, 58, 110, 0.72) 100%),
                url('https://images.unsplash.com/photo-1523240795612-9a054b0db644?w=1920&q=80');
            background-size: cover;
            background-position: center;
            background-repeat: no-repeat;
            color: white;
            padding: 140px 0 100px;
            overflow: hidden;
        }
        
        .hero-background {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            opacity: 0.1;
            z-index: 1;
            background: 
                radial-gradient(circle at 20% 80%, rgba(255, 255, 255, 0.1) 0%, transparent 50%),
                radial-gradient(circle at 80% 20%, rgba(255, 255, 255, 0.1) 0%, transparent 50%);
        }
        
        .hero-content {
            position: relative;
            z-index: 2;
            text-align: center;
            max-width: 900px;
            margin: 0 auto;
        }
        
        .hero-content h1 {
            font-size: 3.5rem;
            font-weight: 700;
            margin-bottom: 20px;
            color: white;
            line-height: 1.2;
            text-shadow: 0 2px 10px rgba(0, 0, 0, 0.2);
        }
        
        .hero-content p {
            font-size: 1.3rem;
            opacity: 0.95;
            margin-bottom: 40px;
            line-height: 1.6;
            max-width: 700px;
            margin-left: auto;
            margin-right: auto;
        }
        
        .hero-stats {
            display: flex;
            justify-content: center;
            gap: 40px;
            margin-top: 60px;
            flex-wrap: wrap;
        }
        
        .hero-stat {
            text-align: center;
        }
        
        .hero-stat-number {
            font-size: 2.5rem;
            font-weight: 700;
            color: white;
            margin-bottom: 5px;
        }
        
        .hero-stat-label {
            font-size: 0.9rem;
            opacity: 0.9;
            text-transform: uppercase;
            letter-spacing: 1px;
        }
        
        /* Formations Section */
        .formations-section {
            padding: 100px 0;
            position: relative;
            background-color: #e8ecf2;
            background-image:
                linear-gradient(180deg, rgba(255, 255, 255, 0.9) 0%, rgba(248, 249, 250, 0.85) 45%, rgba(255, 255, 255, 0.92) 100%),
                url('https://images.unsplash.com/photo-1509062522246-3755977927d7?w=1920&q=80');
            background-size: cover;
            background-position: center;
            background-repeat: no-repeat;
        }
        
        .formations-section .section-header h2 {
            text-shadow: 0 1px 2px rgba(255, 255, 255, 0.9);
        }
        
        .formations-section .section-header p {
            text-shadow: 0 1px 1px rgba(255, 255, 255, 0.8);
        }
        
        .section-header {
            text-align: center;
            margin-bottom: 60px;
        }
        
        .section-header h2 {
            color: #2c5aa0;
            font-size: 2.5rem;
            margin-bottom: 15px;
        }
        
        .section-header p {
            color: #6c757d;
            font-size: 1.2rem;
            max-width: 700px;
            margin: 0 auto;
        }
        
        .formations-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
            gap: 30px;
            margin-bottom: 60px;
        }
        
        .formation-card {
            background: white;
            border-radius: 15px;
            overflow: hidden;
            box-shadow: 0 10px 30px rgba(0, 0, 0, 0.08);
            transition: all 0.4s ease;
            position: relative;
            height: 100%;
        }
        
        .formation-card:hover {
            transform: translateY(-15px);
            box-shadow: 0 20px 40px rgba(0, 0, 0, 0.15);
        }
        
        .formation-header {
            padding: 30px 30px 20px;
            color: white;
            position: relative;
            min-height: 140px;
            display: flex;
            flex-direction: column;
            justify-content: flex-end;
        }
        
        .formation-header.sante {
            background: var(--gradient-secondary);
        }
        
        .formation-header.tourisme {
            background: var(--gradient-accent);
        }
        
        .formation-header.business {
            background: var(--gradient-primary);
        }
        
        .formation-header.devweb {
            background: linear-gradient(135deg, #9c27b0 0%, #ba68c8 100%);
        }
        
        .formation-icon {
            width: 70px;
            height: 70px;
            background: rgba(255, 255, 255, 0.2);
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            margin-bottom: 20px;
            font-size: 1.8rem;
        }
        
        .formation-content {
            padding: 30px;
        }
        
        .formation-content h3 {
            color: #2c5aa0;
            margin-bottom: 15px;
            font-size: 1.3rem;
        }
        
        .formation-content p {
            color: #6c757d;
            margin-bottom: 20px;
            line-height: 1.6;
        }
        
        .formation-features {
            list-style: none;
            padding: 0;
            margin: 0 0 25px 0;
        }
        
        .formation-features li {
            padding: 8px 0;
            border-bottom: 1px solid #f0f0f0;
            display: flex;
            align-items: center;
            gap: 10px;
            color: #555;
        }
        
        .formation-features li:last-child {
            border-bottom: none;
        }
        
        .formation-features i {
            color: #4ecdc4;
        }
        
        /* À propos Section */
        .about-section {
            padding: 100px 0;
            background: white;
        }
        
        .about-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 60px;
            align-items: center;
        }
        
        .about-content h2 {
            color: #2c5aa0;
            margin-bottom: 25px;
            font-size: 2.5rem;
        }
        
        .about-content p {
            color: #6c757d;
            margin-bottom: 20px;
            line-height: 1.7;
            font-size: 1.1rem;
