    <script data-cfasync="false" src="/cdn-cgi/scripts/5c5dd728/cloudflare-static/email-decode.min.js"></script>
    
    <script>
        // ============================================
        // GESTION DE LA PAGE D'ACCUEIL DYNAMIQUE
        // ============================================
        
        document.addEventListener('DOMContentLoaded', function() {
            // Animation au défilement
            function animateOnScroll() {
                const elements = document.querySelectorAll('.animate-in');
                
                elements.forEach(element => {
                    const elementTop = element.getBoundingClientRect().top;
                    const elementVisible = 150;
                    
                    if (elementTop < window.innerHeight - elementVisible) {
                        element.style.opacity = '1';
                        element.style.transform = 'translateY(0)';
                    }
                });
            }
            
            // Initialiser les animations
            document.querySelectorAll('.animate-in').forEach(el => {
                el.style.opacity = '0';
                el.style.transform = 'translateY(30px)';
                el.style.transition = 'opacity 0.75s cubic-bezier(0.22, 1, 0.36, 1), transform 0.75s cubic-bezier(0.34, 1.56, 0.64, 1)';
            });
            
            // Lancer l'animation initiale
            setTimeout(animateOnScroll, 100);
            
            // Écouter le défilement
            window.addEventListener('scroll', animateOnScroll);
            
            // Gestion du slider témoignages
            const testimonials = [
                {
                    avatar: 'S',
                    text: "La formation Développement Web de Convergence m'a permis de me reconvertir professionnellement en seulement 6 mois. Les projets pratiques et l'accompagnement des formateurs ont fait toute la différence.",
                    author: "Sophie Martin",
                    formation: "Diplômée Développement Web, 2023"
                },
                {
                    avatar: 'T',
                    text: "Le programme MBA Management International m'a offert une vision globale du business et des opportunités de networking exceptionnelles. J'ai décroché un poste de directeur marketing avant même la fin de ma formation.",
                    author: "Thomas Leroy",
                    formation: "Diplômé MBA Management, 2022"
                },
                {
                    avatar: 'L',
                    text: "La formation Santé en ligne de Convergence m'a permis de concilier mon travail d'infirmière et mes études. La flexibilité et la qualité des cours sont remarquables.",
                    author: "Lucie Bernard",
                    formation: "Étudiante en Santé Numérique, 2023"
                }
            ];
            
            let currentTestimonial = 0;
            const testimonialCard = document.querySelector('.testimonial-card');
            const prevBtn = document.getElementById('prevTestimonial');
            const nextBtn = document.getElementById('nextTestimonial');
            
            function updateTestimonial() {
                const testimonial = testimonials[currentTestimonial];
                testimonialCard.innerHTML = `
                    <div class="testimonial-avatar">${testimonial.avatar}</div>
                    <div class="testimonial-text">${testimonial.text}</div>
                    <div class="testimonial-author">${testimonial.author}</div>
                    <div class="testimonial-formation">${testimonial.formation}</div>
                `;
                testimonialCard.classList.add('animate-in');
                setTimeout(() => {
                    testimonialCard.style.opacity = '1';
                    testimonialCard.style.transform = 'translateY(0)';
                }, 10);
            }
            
            prevBtn.addEventListener('click', function() {
                testimonialCard.style.opacity = '0';
                testimonialCard.style.transform = 'translateY(30px)';
                setTimeout(() => {
                    currentTestimonial = (currentTestimonial - 1 + testimonials.length) % testimonials.length;
                    updateTestimonial();
                }, 300);
            });
            
            nextBtn.addEventListener('click', function() {
                testimonialCard.style.opacity = '0';
                testimonialCard.style.transform = 'translateY(30px)';
                setTimeout(() => {
                    currentTestimonial = (currentTestimonial + 1) % testimonials.length;
                    updateTestimonial();
                }, 300);
            });
            
            // Auto-slide témoignages
            setInterval(() => {
                nextBtn.click();
            }, 8000);
            
            // Gestion du menu mobile
            const mobileMenuBtn = document.getElementById('mobileMenuBtn');
            const mainNav = document.getElementById('mainNav');
            
            if (mobileMenuBtn) {
                mobileMenuBtn.addEventListener('click', () => {
                    mainNav.classList.toggle('show');
                    mobileMenuBtn.innerHTML = mainNav.classList.contains('show') 
                        ? '<i class="fas fa-times"></i>' 
                        : '<i class="fas fa-bars"></i>';
                });
            }
            
            // Fermer le menu mobile en cliquant sur un lien
            document.querySelectorAll('nav a').forEach(link => {
                link.addEventListener('click', () => {
                    if (mainNav && mainNav.classList.contains('show')) {
                        mainNav.classList.remove('show');
                        mobileMenuBtn.innerHTML = '<i class="fas fa-bars"></i>';
                    }
                });
            });
            
            const cfg = window.groupe1ConvergenceConfig || {};
            const byCity = cfg.eventInscriptionByCity || {};
            const catalog = cfg.eventCatalog || {};
            const citySelectEl = document.getElementById('eventCityKey');
            const slugSelectEl = document.getElementById('eventSlugChoice');
            const eventFormEl = document.getElementById('eventInscriptionForm');
            const feedbackEl = document.getElementById('event-inscription-feedback');
            const submitBtnEl = document.getElementById('eventInscriptionSubmit');
            const honeypotEl = document.getElementById('eventCompanyWebsite');

            function fillEventOptions(cityKey) {
                if (!slugSelectEl) return;
                slugSelectEl.innerHTML = '';
                const slugs = byCity[cityKey];
                if (!cityKey || !slugs || !slugs.length) {
                    slugSelectEl.disabled = true;
                    const ph = document.createElement('option');
                    ph.value = '';
                    ph.textContent = '— Choisissez d\'abord une ville —';
                    slugSelectEl.appendChild(ph);
                    return;
                }
                slugSelectEl.disabled = false;
                const first = document.createElement('option');
                first.value = '';
                first.textContent = '— Choisir un événement —';
                slugSelectEl.appendChild(first);
                slugs.forEach(function(slug) {
                    const meta = catalog[slug];
                    if (!meta) return;
                    const opt = document.createElement('option');
                    opt.value = slug;
                    opt.textContent = meta.label + ' — ' + meta.date_line;
                    slugSelectEl.appendChild(opt);
                });
            }

            if (citySelectEl && slugSelectEl) {
                citySelectEl.addEventListener('change', function() {
                    fillEventOptions(citySelectEl.value);
                });
            }

            if (eventFormEl && feedbackEl && submitBtnEl) {
                eventFormEl.addEventListener('submit', async function(ev) {
                    ev.preventDefault();
                    feedbackEl.className = '';
                    feedbackEl.textContent = '';
                    feedbackEl.style.display = 'none';

                    const cityKey = citySelectEl ? citySelectEl.value : '';
                    const eventSlug = slugSelectEl ? slugSelectEl.value : '';
                    if (!cityKey || !eventSlug) {
                        feedbackEl.className = 'is-error';
                        feedbackEl.textContent = 'Veuillez choisir une ville et un événement.';
                        feedbackEl.style.display = 'block';
                        return;
                    }

                    const payload = {
                        firstName: document.getElementById('eventFirstName').value.trim(),
                        lastName: document.getElementById('eventLastName').value.trim(),
                        email: document.getElementById('eventEmail').value.trim(),
                        phone: document.getElementById('eventPhone').value.trim(),
                        eventSlug: eventSlug,
                        cityKey: cityKey,
                        company_website: honeypotEl ? honeypotEl.value : ''
                    };

                    submitBtnEl.disabled = true;
                    try {
                        const url = cfg.apiEventInscription;
                        if (!url) {
                            throw new Error('Service d\'inscription indisponible.');
                        }
                        const res = await fetch(url, {
                            method: 'POST',
                            headers: { 'Content-Type': 'application/json' },
                            credentials: 'same-origin',
                            body: JSON.stringify(payload)
                        });
                        let data = {};
                        try {
                            data = await res.json();
                        } catch (e2) { /* ignore */ }
                        if (res.ok && data.success) {
                            feedbackEl.className = 'is-success';
                            feedbackEl.textContent = (data.message || 'Inscription enregistrée.') +
                                (data.reference ? ' Référence : ' + data.reference + '.' : '') +
                                ' Vérifiez votre boîte e-mail (et les courriers indésirables).';
                            feedbackEl.style.display = 'block';
                            eventFormEl.reset();
                            if (citySelectEl) citySelectEl.value = '';
                            fillEventOptions('');
                        } else {
                            throw new Error(data.error || ('Erreur ' + res.status));
                        }
                    } catch (err) {
                        feedbackEl.className = 'is-error';
                        feedbackEl.textContent = err.message || 'Une erreur est survenue.';
                        feedbackEl.style.display = 'block';
                    } finally {
                        submitBtnEl.disabled = false;
                    }
                });
            }
            
            // Défilement vers la section demandée via ?section=
            const sectionParam = new URLSearchParams(window.location.search).get('section');
            if (sectionParam) {
                const targetElement = document.getElementById(sectionParam);
                        if (targetElement) {
                            window.scrollTo({
                                top: targetElement.offsetTop - 80,
                                behavior: 'smooth'
                            });
                        }
                    }
            
            console.log('Page d\'accueil dynamique initialisée avec succès !');
        });
        
    </script>
